INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(23752, 'koKR', 'Vexallus wyładowuje czystą energię!', '', 0),
(23753, 'koKR', '%s zaczyna czerpać moc z pobliskiego Kryształu spaczenia. Zniszcz go!', '', 0),
(23781, 'koKR', 'Vexallus się przeciąża!', '', 0),
(23840, 'koKR', 'Moc! Więcej, więcej, więcej!', '', 0),
(23841, 'koKR', 'Kipi i pali...', '', 0),
(23842, 'koKR', 'Nigdy nie przestanę. Nigdy...', '', 0),
(23845, 'koKR', 'Jest MOJA!', '', 0),
(23847, 'koKR', 'Precz od moich kryształów!', '', 0),
(25386, 'koKR', 'Nie róbcie takich zadowolonych min! Wiem, co sobie myślicie, ale Twierdza Burz była tylko chwilowym niepowodzeniem. Naprawdę sądziliście, że powierzyłbym przyszłość jakiemuś ślepemu kundlowi, pół-nocnemu elfowi?', '', 0),
(25387, 'koKR', 'O nie, był tylko narzędziem, stopniem do znacznie większego planu! Wszystko prowadziło do tej chwili... i tym razem nie przeszkodzicie!', '', 0),
(25388, 'koKR', 'Zemsta płonie!', '', 0),
(25389, 'koKR', 'Felomin Ashal!', '', 0),
(25390, 'koKR', 'Wywrócę wasz świat... do góry... nogami.', '', 0),
(25391, 'koKR', 'Mistrzu, daj mi siłę.', '', 0),
(25392, 'koKR', 'Nie czujcie się... zbyt swobodnie.', '', 0),
(25393, 'koKR', 'Moja śmierć niczego nie zmieni! Mistrz was dopadnie! Utoniecie we własnej krwi! Świat spłonie! Aaach!', '', 0),
(25423, 'koKR', 'Tylko marnujecie mój czas!', '', 0),
(25424, 'koKR', 'Mój głód nie zna granic!', '', 0),
(25425, 'koKR', 'Tak!! Jestem bogiem!', '', 0),
(25426, 'koKR', 'Nie... więcej, muszę mieć więcej!!', '', 0),
(25428, 'koKR', 'Dość tego rozpraszania!', '', 0),
(25430, 'koKR', '', 'Unicestwić ich.', 0),
(25431, 'koKR', '', 'Nie tak to... planowałam.', 0),
(25432, 'koKR', '', 'Och, cóż za okropność!', 0),
(25433, 'koKR', '', 'No proszę, ale z ciebie $gszczęściarz:szczęściara;, co?', 0),
(25434, 'koKR', '', 'Teraz zaczynam się irytować.', 0),
(25435, 'koKR', '', 'Do diabła ze sługami! Sama cię wykończę!', 0),
(25436, 'koKR', '', 'To ja nazywam dobrym początkiem.', 0),
(25437, 'koKR', '', 'Mogłabym przysiąc, że było was więcej...', 0),
(25438, 'koKR', '', 'To już niezbyt „drużyna”, prawda?', 0),
(25439, 'koKR', '', 'Jedynka to taka samotna liczba.', 0),
(25440, 'koKR', '', 'Było naprawdę zabawnie.', 0),
(25623, 'koKR', 'Wyssać... życie!', '', 0),
(25625, 'koKR', 'Uwol...nić.', '', 0),
(25626, 'koKR', 'Nie do...o...pa...nowania.', '', 0),
(25627, 'koKR', 'Po...chłonąć.', '', 0),
(34142, 'koKR', 'Jestem niezwyciężony!', '', 0);
